pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);
        vm.prank(caller);
        c.withdraw();
        uint256 balance = c.balances(caller);
        assertTrue(balance == 0);
    }
}
